"""Head-side extent proposal; no decisions are generated by this script."""
import review_grenade_remaining as g
r=g.r
e=r.e
base=e.body_options

def proposals(row,a,shuffle=False):
    opts=base(row,a,shuffle=False)
    if 'G' not in opts:return opts
    x0,y0,x1,y1=opts['G']
    side=max(6,(x1-x0)//4)
    left=row['recording'] in ('2023-09-21_101416','2023-09-21_104749')
    lo,hi=(x0,x0+side) if left else (x1-side,x1)
    sm=e.cv2.GaussianBlur(a.astype(e.np.float32),(3,3),0)
    patch=sm[y0:min(a.shape[0],y1+30),lo:hi]
    yy,xx=e.np.where(patch>50)
    if len(yy):opts['K']=[x0,y0,x1,min(a.shape[0],y0+int(yy.max())+7)]
    return opts

e.body_options=proposals
r.OUT=r.ROOT/'DataSet/paired_assistant_mortar_head_extent'

if __name__=='__main__':
    import sys
    r.build(sys.argv[1],int(sys.argv[2]),int(sys.argv[3]),'K')
